    question: '[Exercise 3.4 Q1, Q2, Q4, Q5, Q7, Q10] Classify each compound statement as a Tautology, a Contradiction, or Neither:\n(1) $p \\wedge \\sim(p \\wedge q)$,\n(2) $(p \\vee q) \\wedge (\\sim p \\wedge \\sim q)$,\n(4) $\\sim(p \\vee q) \\rightarrow (\\sim p \\wedge \\sim q)$,\n(5) $p \\wedge \\sim(p \\vee q)$,\n(7) $(p \\wedge q) \\rightarrow (p \\vee q)$,\n(10) $[\\sim q \\wedge (p \\rightarrow q)] \\rightarrow \\sim p$.',
