    id: 'addmath-f2-ch3-ex3.5-3.6-networks-arguments',
    cls: 'Form 2',
    subject: 'Additional Mathematics',
    topic: 'Chapter 3: Logic',
    subTopic: 'Electrical networks and validity of arguments',
    exerciseRef: 'Exercise 3.5 Q2 & Exercise 3.6 Q1–Q5 (Pages 49, 52)',
    textbookTitle: ADD_MATH_F2_BOOK,
    question: '[Exercise 3.5 Q2 & Exercise 3.6 Q1–Q4] (a) In electrical switching networks between terminals $T_1$ and $T_2$, how are switches connected in series and switches connected in parallel represented in symbolic logic? (b) Write the compound statement for a network having parallel switches $\\sim r$ and $p$ connected in series with switch $q$ (Ex 3.5 Q2b). (c) Test the validity of the arguments: (i) "If I am clever, then I know how to reason. I do not know how to reason. Therefore, I am not clever." (Ex 3.6 Q1), and (ii) "If you bought bread, then you went to the supermarket. You did not buy bread. Therefore, you did not go to the supermarket." (Ex 3.6 Q4).',
    options: [
      '(a) Series $= \\text{Conjunction } (\\wedge)$, Parallel $= \\text{Disjunction } (\\vee)$ ; (b) $(\\sim r \\vee p) \\wedge q$ ; (c) (i) Valid (Modus Tollens), (ii) Not valid (Fallacy of the Inverse)',
      '(a) Series $= \\text{Disjunction } (\\vee)$, Parallel $= \\text{Conjunction } (\\wedge)$ ; (b) $(\\sim r \\wedge p) \\vee q$ ; (c) (i) Valid, (ii) Valid',
      '(a) Series $= \\text{Conjunction } (\\wedge)$, Parallel $= \\text{Disjunction } (\\vee)$ ; (b) $(\\sim r \\vee p) \\wedge q$ ; (c) (i) Not valid, (ii) Valid',
      '(a) Series $= \\text{Implication } (\\rightarrow)$, Parallel $= \\text{Biconditional } (\\leftrightarrow)$ ; (b) $\\sim r \\vee (p \\wedge q)$ ; (c) (i) Valid, (ii) Not valid',
    ],
    correctIndex: 0,
    explanation: '(a) Series switches require both to be closed ($p \\wedge q$), while parallel switches allow current if either is closed ($p \\vee q$). (b) Parallel $(\\sim r \\vee p)$ in series with $q$ gives $(\\sim r \\vee p) \\wedge q$. (c) Argument (i) has form $[(p \\rightarrow q) \\wedge \\sim q] \\rightarrow \\sim p$, which is a tautology (Valid). Argument (ii) has form $[(p \\rightarrow q) \\wedge \\sim p] \\rightarrow \\sim q$, which is False when $p=\\text{F}, q=\\text{T}$ (Not valid) (Pages 104–105).',
    hint: 'An argument is valid if and only if $[P_1 \\wedge P_2 \\wedge \\dots \\wedge P_n] \\rightarrow C$ is a tautology.',
