      '(a) $x^2 + y^2 - 4x - 6y + 4 = 0$ ; (b) Centre $P(-3, -2)$, distance $r = 5$ ; (c) $3x + y - 7 = 0$ ; (d) $3x^2 + 3y^2 - 20x + 12 = 0$',
      '(a) $x^2 + y^2 + 4x + 6y + 13 = 0$ ; (b) Centre $P(3, 2)$, distance $r = 12$ ; (c) $3x - y + 7 = 0$ ; (d) $x^2 + y^2 + 20x + 12 = 0$',
      '(a) $x^2 + y^2 + 4x + 6y + 4 = 0$ ; (b) Centre $P(6, 4)$, distance $r = 5$ ; (c) $x - 3y + 7 = 0$ ; (d) $3x^2 + 3y^2 + 20x + 12 = 0$',
