    question: '[Exercise 3.4 Q1, Q2, Q4 & Rev 3 Q8] (a) Find the vertical asymptotes of $f(x) = \\frac{3x - 5}{x^2 + x - 6}$ and $h(x) = \\frac{x^2 - 5x + 1}{x^2 + 9}$. (b) Find the horizontal asymptotes of $p(x) = \\frac{-3x - 8}{x + 1}$ and $q(x) = \\frac{x^2 - 4}{2x^2 + 5x}$. (c) Find $E, F,$ and $G$ if $E + \\frac{Fx}{(x - 3)^2} - \\frac{5}{x - 3} - \\frac{G}{x + 2} = \\frac{-2x^3 + x^2 + 39x - 42}{(x - 3)^2(x + 2)}$.',
