function rotateOptionsDeterministic(
  options: [string, string, string, string],
  correctIndex: number,
  seed: number
): { options: [string, string, string, string]; correctIndex: number } {
  const safeCorrect = options[correctIndex] ?? options[0];
  const shift = ((seed % 4) + 4) % 4;
  const rotated: [string, string, string, string] = [
    options[(0 + shift) % 4],
    options[(1 + shift) % 4],
    options[(2 + shift) % 4],
    options[(3 + shift) % 4],
  ];
  const newCorrectIdx = Math.max(0, rotated.indexOf(safeCorrect));
  return { options: rotated, correctIndex: newCorrectIdx };
}

