      subject: 'Additional Mathematics',
      topic: 'Chapter 1: Numbers',
      subTopic: 'Number patterns',
      exerciseRef: 'Exercise 1.1, Qn 3(a)-(b) (Page 5)',
      textbookTitle: ADD_MATH_F1_BOOK,
