  addMathSubQuestions.forEach((item, idx) => {
    const rotated = rotateOptionsDeterministic(item.options, item.correctIndex, idx + 1);
    expanded.push({
      ...item,
      id: `addmath-f1-sub-${idx + 1}`,
      options: rotated.options,
      correctIndex: rotated.correctIndex,
    });
  });

  // (Old conceptScenarios loop for Form 1 Basic Mathematics removed — replaced by complete MATH_F1_BANK)

  type DistinctExerciseTuple = [
    subTopic: string,
    exerciseRef: string,
    question: string,
    ans: string,
    d1: string,
    d2: string,
    d3: string,
    explanation?: string,
    isMultipleChoice?: boolean
  ];

  const pushDistinctChapterBank = (
    idPrefix: string,
    cls: string,
    subject: string,
    topic: string,
    textbookTitle: string,
    items: DistinctExerciseTuple[]
  ) => {
    items.forEach(([subTopic, exerciseRef, q, ans, d1, d2, d3, explanation, isMultipleChoice], idx) => {
      const k = idx + 1;
      const rot = rotateOptionsDeterministic([ans, d1, d2, d3], 0, k);
      const autoMcq =
        isMultipleChoice !== undefined
          ? isMultipleChoice
          : /\b(choose the most|multiple choice|write true|write t for|true or false|match each item|match the following)\b/i.test(q);
      expanded.push({
        id: `${idPrefix}-${k}`,
        cls,
        subject,
        topic,
        subTopic,
        exerciseRef,
        textbookTitle,
        question: `[${exerciseRef}] ${q}`,
        options: rot.options,
        correctIndex: rot.correctIndex,
        explanation: explanation || `Correct Answer: ${ans}`,
        hint: `Apply the ${cls} ${subject} (${topic} — ${subTopic}) textbook method step by step.`,
        isMultipleChoice: autoMcq,
      });
    });
  };

