      'Four Processes of River Erosion and How Each Shapes the Riverbed and Banks',
      'Exercise 2.4 Q2',
      'Explain the processes of river erosion and describe how each process shapes the riverbed and banks:',
      'River erosion operates through four interacting processes: (1) **Hydraulic Action** — the sheer mechanical force of fast-flowing water compressively forcing air into cracks in the bed and banks, shattering and prizing rock fragments loose (undercutting banks and plunge pools); (2) **Corrasion (Abrasion)** — the scraping, grinding, and scouring of the riverbed and banks by boulders, pebbles, and sand carried as load, deepening the channel and drilling circular potholes in the rocky bed; (3) **Corrosion (Solution)** — the chemical dissolving of soluble minerals (such as limestone/chalk) from the bed and banks by slightly acidic river water; and (4) **Attrition** — the mutual collision and rubbing of rock fragments carried in the water against one another, breaking them into smaller, smoother, and rounder pebbles while reducing load size',
