      'Exercise 3.7 Q1(a) & Q1(b)',
      '(a) Define the term "intervisibility" as used in map reading. (b) List factors affecting intervisibility between two points on a map:',
      '(a) **Intervisibility** is the ability of an observer at one point on the ground (or map) to see another point directly along an unobstructed straight line of sight (if Point A can see Point B, then Point B is intervisible with Point A). (b) **Factors affecting intervisibility**: (1) **Shape of the intervening slope** (concave slopes allow intervisibility; convex slopes block intervisibility); (2) **Presence of intervening higher relief** (a hill, ridge, or spur higher than the line of sight blocks view); and (3) **Presence of tall vegetation or artificial structures** (dense forests or tall buildings between the two points)',
