      '(c) Determining intervisibility is vital for siting microwave/mobile/TV telecommunication towers (which require unobstructed line-of-sight), aligning land-surveying instruments for straight roads, railways, canals, and pipelines, placing military/forestry observation watchtowers, and ensuring safe sight-distances on highways. (d) By inspecting **contour lines** along the straight line joining two points: if there is an intervening contour of higher elevation than both points, or if contours are wide apart at the top and closely packed near the bottom (**convex slope**), the two points are **not intervisible**; if the land dips lower between them (valley) or contours are closely packed at the top and wide at the bottom (**concave slope**), the points are **intervisible**',
