        '(a) **Holozoic nutrition**: organisms take in (ingest) complex solid or liquid organic food, digest it internally using enzymes, absorb the soluble nutrients, assimilate them, and egest undigested remains (*Examples*: humans, lions, cows, amoeba). (b) **Saprophytic nutrition**: organisms feed on dead and decaying organic matter by secreting digestive enzymes externally onto the substrate (extracellular digestion) and absorbing the soluble products (*Examples*: mushrooms, mucor/bread mould, yeast, and putrefying bacteria). (c) **Symbiotic nutrition**: a close nutritional association between two organisms of different species living together, including mutualism, commensalism, and parasitism (*Examples*: lichens, nitrogen-fixing *Rhizobium* in legume root nodules, and tapeworms in humans)',
