        'Explain the meaning of the following: (a) commensalism; (b) parasitism; and (c) mutualism.',
        '(a) **Commensalism**: a symbiotic association between two organisms of different species in which **one organism (the commensal) benefits** (e.g., food scraps, shelter, or transport) while the **other organism (the host) is neither harmed nor benefited** (*e.g., remora fish and shark, or epiphytes on forest trees*). (b) **Parasitism**: a relationship in which **one organism (the parasite) benefits** by living on (ectoparasite, e.g., ticks, lice) or inside (endoparasite, e.g., *Plasmodium*, tapeworm) another organism (**the host**), obtaining nutrients at the host’s expense and **causing harm or disease to the host**. (c) **Mutualism**: a symbiotic association in which **both organisms benefit** from living together (*e.g., nitrogen-fixing Rhizobium bacteria in legume root nodules, cellulose-digesting bacteria in ruminant stomachs, or lichens*)',
