        'Revision Exercise 2 Q1',
        'Differentiate between food and nutrient, kwashiorkor and marasmus, macronutrients and micronutrients.',
        '(1) **Food vs. Nutrient**: **Food** is any nutritious edible solid or liquid consumed by an organism (e.g., maize, beans, milk, fish), whereas **nutrients** are the specific chemical substances contained in food (carbohydrates, proteins, lipids, vitamins, minerals, water) that the body absorbs and uses for energy, growth, and regulation. (2) **Kwashiorkor vs. Marasmus**: **Kwashiorkor** is a protein-deficiency disorder (typically in children aged 1–5 years fed a high-carbohydrate, low-protein diet after weaning) characterized by **oedema (swollen abdomen, face, and feet)**, thin limbs, enlarged fatty liver, and sparse reddish hair; **Marasmus** is acute **total energy/calorie starvation** (deficiency of all food nutrients, especially carbohydrates and fats, often in infants under 1 year) characterized by **extreme emaciation/muscle wasting**, prominent ribs, wrinkled loose skin, sunken eyes ("old man\'s face"), and **no oedema**. (3) **Macronutrients vs. Micronutrients**: **Macronutrients** (carbohydrates, proteins, lipids) are needed by the body in **large daily quantities (grams)** to provide energy and build tissues, whereas **micronutrients** (vitamins and mineral salts) are needed in **small/trace quantities (milligrams or micrograms)** to regulate enzymes, immunity, and physiological processes',
