        '**Dietary & Lifestyle Modifications**: (1) **Eat slowly and chew food thoroughly** with the mouth closed, and avoid gulping carbonated drinks, chewing gum, or drinking through straws; (2) **Soak and cook legumes (beans, peas) thoroughly** and introduce high-fibre foods gradually rather than abruptly in excessive amounts; (3) **Limit gas-producing fermentable foods** (such as raw cabbage, onions, carbonated sodas, and lactose-heavy dairy if lactose intolerant); and (4) **Eat smaller, regular meals and engage in regular physical exercise/walking**. **Impact on the digestive process**: Chewing slowly reduces **aerophagia** (swallowing excess air) and breaks food into smaller particles with larger surface area for complete enzymatic digestion in the stomach and small intestine—preventing undigested carbohydrates/oligosaccharides from reaching the colon where bacteria would ferment them into excess gases ($\\text{CO}_2, \\text{H}_2, \\text{CH}_4, \\text{H}_2\\text{S}$); exercise stimulates smooth **peristalsis** so trapped gas passes naturally without painful bloating',
        'Swallowing food whole without chewing and drinking 5 litres of carbonated soda at once',
        'Avoiding all water and lying down immediately after eating raw unsoaked beans',
        'Flatulence is controlled by stopping breathing during meals',
        'Step 1: Modifications — chew thoroughly/eat slowly, soak & cook beans well, limit carbonated drinks/excess fermentable sugars, exercise regularly. Step 2: Digestive impact — minimizes swallowed air, ensures complete enzymatic breakdown in the small intestine (reducing colonic bacterial fermentation of undigested carbs), and promotes smooth peristaltic transit.',
