        '(a) **Lots of sugar**: Oral bacteria ferment sugars into acids that erode tooth enamel causing **dental caries (tooth decay)**, while excess calories cause **obesity, type 2 diabetes mellitus, and fermentative bloating**. (b) **No or little fibre (roughage)**: Peristaltic contractions of the alimentary canal lack bulk to grip against, leading to slow bowel movement, hard dry stools, **chronic constipation, haemorrhoids (piles), and increased risk of colon disorders**. (c) **Too much fats, oils, or spices**: Delays gastric emptying, irritates the gastric mucosa, and relaxes the cardiac sphincter, causing **indigestion (dyspepsia), heartburn (acid reflux), gastritis, peptic ulcers, gallstones, and obesity**. (d) **Inadequate water and fluids**: The colon absorbs excessive water from undigested matter, resulting in **hard, dry faeces and severe constipation**, as well as impaired hydrolysis and dehydration. (e) **Wearing very tight clothes around the abdomen**: Compresses the stomach and increases intra-abdominal pressure, forcing acidic gastric chyme upward through the cardiac sphincter into the oesophagus and causing **heartburn / gastro-oesophageal acid reflux (GERD)** and impaired peristalsis',
