        'Revision Exercise 3 Q4',
        'How does osmosis affect the health of plant cells? What might happen to a plant if it is watered with saltwater instead of fresh water?',
        '**Effect of Osmosis on Plant Cell Health**: When watered with **fresh water** (which is **hypotonic** to root hair cell sap), plant cells absorb water by **endosmosis**; the vacuole swells and pushes the cytoplasm firmly against the rigid cellulose cell wall, creating **turgor pressure** (whilst the wall exerts equal and opposite wall pressure). This **turgidity** keeps herbaceous stems upright, holds leaves flat and spread out to trap sunlight for photosynthesis, and opens guard cells (stomata) for gas exchange. **If watered with saltwater**: Saltwater is **hypertonic** (has a lower water potential) relative to the cell sap of root hair cells. Consequently, **water moves out of the plant root cells into the soil by exosmosis**; the vacuoles shrink, the cytoplasm pulls away from the cell wall (**plasmolysis**), cells become **flaccid**, the plant **wilts** severely, stomata close (halting photosynthesis), and the plant **dehydrates and dies** ("physiological drought")',
