        'How Xylem Vessels Are Adapted to Their Functions',
        'Exercise 4.1 Q2',
        'Describe how xylem vessels are adapted to their functions.',
        'Xylem vessels are adapted for the upward transport of water and mineral salts and mechanical support in the following ways: (1) They consist of **dead, hollow cells lacking protoplasm (no cytoplasm, nucleus, or organelles)** and their **cross-walls (end walls) have broken down completely**, forming a continuous, unobstructed open pipeline from roots to leaves; (2) Their cellulose cell walls are thickened and impregnated with waterproof **lignin** (in annular, spiral, reticulate, or pitted patterns), which gives high **mechanical strength** and prevents the vessels from collapsing under the strong negative tension of transpiration pull; (3) Their **narrow lumen** enhances upward movement of water by **capillarity** (adhesion and cohesion); and (4) Their side walls contain unlignified **bordered pits** that allow lateral movement of water and minerals to adjacent living cells',
