        'The vena cava would immediately turn into an artery and pump oxygenated blood to the body',
        'Step 1: Identify role of aorta — main systemic artery carrying oxygenated blood from the left ventricle to all body organs (brain, heart muscle via coronary arteries, kidneys, etc.). Step 2: Consequences of blockage — complete cutoff of oxygenated blood to brain and body tissues + massive pressure buildup in the left ventricle $\\rightarrow$ heart failure, brain hypoxia, and rapid death.',
