        'Importance of Blood Circulation in Mammals',
        'Exercise 5.2 Q3',
        'Explain the importance of blood circulation.',
        'Blood circulation is essential in mammals because it: (1) **Transports oxygen** from the lungs to all respiring body cells and **carbon dioxide** from cells to the lungs for exhalation; (2) **Distributes soluble digested food nutrients** (glucose, amino acids, fatty acids, vitamins, mineral salts) from the small intestine and liver to all body tissues; (3) **Transports nitrogenous and metabolic waste products** (urea from the liver, uric acid, creatinine, excess salts, and water) to the kidneys and skin for excretion; (4) **Transports hormones** from endocrine glands (e.g., insulin, adrenaline, thyroxine) to target organs for chemical coordination; (5) **Defends the body against disease and blood loss** by circulating white blood cells (phagocytes and lymphocytes), antibodies, and clotting factors/platelets; and (6) **Regulates body temperature and pH** by distributing heat evenly from the liver and muscles to the skin',
