        'Exercise 5.2 Q4',
        'Describe what will happen to the flow of blood in the left side of the heart if the bicuspid valve stops to function effectively.',
        'If the **bicuspid (mitral) valve** fails to close properly (**mitral valve incompetence / regurgitation**): (1) When the **left ventricle contracts (ventricular systole)**, a significant portion of **oxygenated blood leaks backward (regurgitates) into the left atrium** instead of being pumped forward into the **aorta**; (2) This **reduces cardiac output** (less oxygenated blood reaches the systemic arteries and body tissues), causing **fatigue, dizziness, and weakness**; and (3) The backflow of blood increases pressure and volume inside the **left atrium and pulmonary veins**, causing blood and fluid to back up into the **lungs (pulmonary congestion / pulmonary oedema)**, resulting in **shortness of breath (dyspnoea)**, a heart murmur, and eventual **left-sided heart failure**',
